package com.mobilegaming.domain;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;

abstract class CurrentUser { final UserRepository users; CurrentUser(UserRepository u){users=u;} User me(){return users.findById(UUID.fromString(SecurityContextHolder.getContext().getAuthentication().getName())).orElseThrow(()->new NoSuchElementException("User not found"));} }
@RestController @RequestMapping("/players") class PlayerController extends CurrentUser { final PlayerRepository players;final AchievementRepository achievements;final PlayerAchievementRepository earned;final SocialRepository social; PlayerController(UserRepository u,PlayerRepository p,AchievementRepository a,PlayerAchievementRepository e,SocialRepository s){super(u);players=p;achievements=a;earned=e;social=s;} Player player(UUID game){return players.findByUserIdAndGameId(me().id,game).orElseGet(()->{Player p=new Player();p.userId=me().id;p.gameId=game;return players.save(p);});}@GetMapping("/{gameId}") Player profile(@PathVariable UUID gameId){return player(gameId);}@PutMapping("/{gameId}/progress") Player progress(@PathVariable UUID gameId,@Valid @RequestBody ProgressRequest r){Player p=player(gameId);p.playerLevel=r.playerLevel();p.experiencePoints=r.experiencePoints();p.virtualCurrency=r.virtualCurrency();p.playerSegment=r.playerSegment();p.lastPlayDate=Instant.now();return players.save(p);}@GetMapping("/{gameId}/achievements") List<PlayerAchievement> achievements(@PathVariable UUID gameId){return earned.findByPlayerId(player(gameId).id);}@PostMapping("/{gameId}/achievements/{id}/unlock") PlayerAchievement unlock(@PathVariable UUID gameId,@PathVariable UUID id){Player p=player(gameId);achievements.findById(id).orElseThrow(()->new NoSuchElementException("Achievement not found"));PlayerAchievement pa=earned.findByPlayerIdAndAchievementId(p.id,id).orElseGet(()->{PlayerAchievement n=new PlayerAchievement();n.playerId=p.id;n.achievementId=id;return n;});pa.unlockedDate=Instant.now();pa.progress=100;return earned.save(pa);}@GetMapping("/{gameId}/social") List<SocialConnection> social(@PathVariable UUID gameId){return social.findByPlayerId(player(gameId).id);} }
@RestController @RequestMapping("/sessions") class SessionController extends CurrentUser {final PlayerRepository players;final SessionRepository sessions;SessionController(UserRepository u,PlayerRepository p,SessionRepository s){super(u);players=p;sessions=s;}@PostMapping("/start") ResponseEntity<GameSession> start(@Valid @RequestBody SessionStartRequest r){Player p=players.findByUserIdAndGameId(me().id,r.gameId()).orElseThrow(()->new IllegalArgumentException("Create a player profile first"));GameSession s=new GameSession();s.playerId=p.id;s.gameId=r.gameId();s.deviceType=r.deviceType();s.deviceOs=r.deviceOs();s.appVersion=r.appVersion();p.totalSessions++;p.lastPlayDate=Instant.now();players.save(p);return ResponseEntity.status(201).body(sessions.save(s));}@PutMapping("/{id}/update") GameSession update(@PathVariable UUID id,@Valid @RequestBody SessionUpdateRequest r){GameSession s=sessions.findById(id).orElseThrow(()->new NoSuchElementException("Session not found"));s.actionsPerformed=r.actionsPerformed();s.scoreAchieved=r.scoreAchieved();s.levelsCompleted=r.levelsCompleted();return sessions.save(s);}@PostMapping("/{id}/end") GameSession end(@PathVariable UUID id){GameSession s=sessions.findById(id).orElseThrow(()->new NoSuchElementException("Session not found"));s.sessionEnd=Instant.now();s.durationSeconds=(int)Duration.between(s.sessionStart,s.sessionEnd).toSeconds();Player p=players.findById(s.playerId).orElseThrow();p.totalPlayTime+=s.durationSeconds;players.save(p);return sessions.save(s);}@GetMapping("/history") List<GameSession> history(@RequestParam UUID gameId){return sessions.findByPlayerIdOrderBySessionStartDesc(players.findByUserIdAndGameId(me().id,gameId).orElseThrow().id);} }
@RestController @RequestMapping("/purchases") class PurchaseController extends CurrentUser {final PlayerRepository players;final PurchaseRepository purchases;PurchaseController(UserRepository u,PlayerRepository p,PurchaseRepository q){super(u);players=p;purchases=q;}@PostMapping("/initiate") ResponseEntity<Purchase> initiate(@Valid @RequestBody PurchaseRequest r){Player p=players.findByUserIdAndGameId(me().id,r.gameId()).orElseThrow(()->new IllegalArgumentException("Player not enrolled in game"));Purchase q=new Purchase();q.playerId=p.id;q.gameId=r.gameId();q.productId=r.productId();q.productName=r.productName();q.purchaseAmount=r.purchaseAmount();q.currency=r.currency();q.platform=r.platform();q.receiptData=r.receiptData();q.transactionId=UUID.randomUUID().toString();return ResponseEntity.status(201).body(purchases.save(q));}@PostMapping("/validate") Purchase validate(@RequestParam UUID id){Purchase p=purchases.findById(id).orElseThrow(()->new NoSuchElementException("Purchase not found"));p.status=PurchaseStatus.COMPLETED;return purchases.save(p);}@GetMapping("/history") List<Purchase> history(@RequestParam UUID gameId){return purchases.findByPlayerIdOrderByTransactionDateDesc(players.findByUserIdAndGameId(me().id,gameId).orElseThrow().id);}@PostMapping("/refund") @PreAuthorize("hasAnyRole('LIVE_OPS_MANAGER','ADMIN')") Purchase refund(@RequestParam UUID id){Purchase p=purchases.findById(id).orElseThrow(()->new NoSuchElementException("Purchase not found"));p.status=PurchaseStatus.REFUNDED;return purchases.save(p);} }
@RestController @RequestMapping("/events") class EventController {final EventRepository events;EventController(EventRepository e){events=e;}@GetMapping("/active") List<LiveEvent> active(){return events.findByActiveTrue();}@PostMapping @PreAuthorize("hasAnyRole('LIVE_OPS_MANAGER','ADMIN')") ResponseEntity<LiveEvent> create(@Valid @RequestBody EventRequest r){if(!r.endDate().isAfter(r.startDate()))throw new IllegalArgumentException("End date must be after start date");LiveEvent e=map(new LiveEvent(),r);return ResponseEntity.status(201).body(events.save(e));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('LIVE_OPS_MANAGER','ADMIN')") LiveEvent update(@PathVariable UUID id,@Valid @RequestBody EventRequest r){return events.save(map(events.findById(id).orElseThrow(()->new NoSuchElementException("Event not found")),r));}@DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('LIVE_OPS_MANAGER','ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void cancel(@PathVariable UUID id){LiveEvent e=events.findById(id).orElseThrow(()->new NoSuchElementException("Event not found"));e.active=false;events.save(e);}private LiveEvent map(LiveEvent e,EventRequest r){e.gameId=r.gameId();e.eventName=r.eventName();e.startDate=r.startDate();e.endDate=r.endDate();e.eventType=r.eventType();e.configuration=r.configuration();e.active=r.active();return e;} }
